// PerfilUser.jsx

import React, {useState, useEffect} from 'react';
import './Perfil_user.css';
import NavMenu from '../../navMenu/NavMenu';
import { FiUser, FiMail, FiPhone, FiLock, FiImage } from 'react-icons/fi';
import { getUserData, setUserData } from '../LocalStorangUser/LocalstorangUser';

import { useSelector } from 'react-redux';

const PerfilUser = () => {
  const [loading, setLoading] = useState(true);
  const user = useSelector((state)=>state.USER)
  const [imagePreview, setImagePreview] = useState(null);
  const dispatch = useDispatch();
  const navigate = useNavigate();






  useEffect(() => {
    const timer = setTimeout(() => {
      setLoading(false);
    }, 3000);
    return () => clearTimeout(timer);
  }, [dispatch]);

  useEffect(() => {
    const storedUser = getUserData();
    if (!user || user.state === "false") {
      if (!storedUser || storedUser.state === "false") {
        navigate('/');
      } else {
       //alert(storedUser.id);
        dispatch(Buscar_Orders_Users(storedUser.id));
        dispatch(LogalstorangUSER(storedUser));
      }
    } else {
      setUserData(user);
    }
  }, [navigate, user, dispatch]);

  const handleImageChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setImagePreview(reader.result);
      };
      reader.readAsDataURL(file);
    }
  };
  useEffect(() => {
    setImagePreview(User.url)
   
  }, [User]);
  return (
    <>
      <NavMenu className="nav-menu" />
      <div className='body-user-perfil-centar'>
        <div className='form-perfil'>
          <h2>PERFIL USUARIO</h2>
          <div className="Login-container-input">
            <div className="input-group">
              <FiUser className="input-icon" />
              <input type='text' name='nombre' placeholder='Nombre' className="perfil-user-input" />
            </div>
            <div className="input-container perfil-user-apellido">
              <FiUser className="input-icon" />
              <input type='text' name='apellido' placeholder='Apellido' className="perfil-user-input" />
            </div>
            <div className="input-container perfil-user-celular">
              <FiPhone className="input-icon" />
              <input type='tel' name='celular' placeholder='Celular' className="perfil-user-input" />
            </div>
            <div className="input-container perfil-user-email">
              <FiMail className="input-icon" />
              <input type='email' name='email' placeholder='Correo' className="perfil-user-input" />
            </div>
            <div className="input-container perfil-user-pass">
              <FiLock className="input-icon" />
              <input type='password' name='pass' placeholder='Contraseña' className="perfil-user-input" />
            </div>
            <div className="input-group">
              <FiImage className="input-icon" />
              <input type="file" name="image" accept="image/*" className="perfil-user-input" onChange={handleImageChange} />
            </div>
          </div>
          <div className="btn-editar">Editar</div>
          </div>
          <div className="image-preview">
            {/* Aquí puedes mostrar la imagen de previsualización si lo deseas */}
            <img src={imagePreview} alt="Preview" />
          </div>
        </div>
      
    </>
  );
};

export default PerfilUser;
